const LONG_SECTION_CHARS=900;const LONG_SECTION_ROWS=30;const SVG_NS="http://www.w3.org/2000/svg";const NUMERIC_CELL=/^[+\-−]?\d+(?:\.\d+)?(?:°\d+′\d+(?:\.\d+)?″)?$/;const NEUTRAL_CELL=(text)=>text===""||text==="—";function numericColumns(model){return model.columns.map((_column,index)=>{if(index===0)return false;const cells=model.rows.map((row)=>String(row[index]==null?"":row[index]).trim());return cells.some((text)=>NUMERIC_CELL.test(text))&&cells.every((text)=>NEUTRAL_CELL(text)||NUMERIC_CELL.test(text));});}
const TABLE_GLYPHS=(()=>{const glyphs=window.ArmillaryChartGlyphs;const labels=window.ArmillaryLabels;const points=window.ChartWheelModel&&window.ChartWheelModel.POINTS;const bodies=new Map();const keys=new Map();const signs=new Map();if(!glyphs||!labels||!points)return{bodies,keys,signs,glyphs:null};const vocabulary=labels.VOCABULARIES;[vocabulary.body_backend_name,vocabulary.node_backend_name,vocabulary.lunar_apsis_backend_name].forEach((table)=>{Object.entries(table).forEach(([key,name])=>{const point=points[key];if(!point||!glyphs.GLYPHS[point.glyph])return;bodies.set(name,point.glyph);keys.set(key,point.glyph);});});Object.entries(vocabulary.zodiac_sign).forEach(([key,name])=>{if(glyphs.GLYPHS[key])signs.set(name,key);});return{bodies,keys,signs,glyphs:glyphs.GLYPHS};})();const SIGN_AT_START=new RegExp(`^(${[...TABLE_GLYPHS.signs.keys()].join("|")||"(?!)"}) (?=\\d)`);const PAIR_SEPARATOR=" — ";function tableGlyph(key){const[x0,,x1]=TABLE_GLYPHS.glyphs[key].bbox;const svg=document.createElementNS(SVG_NS,"svg");svg.setAttribute("class","cell-glyph");svg.setAttribute("viewBox",`${Math.round((x0+x1)/2)-525} -810 1050 1050`);svg.setAttribute("aria-hidden","true");svg.setAttribute("focusable","false");svg.dataset.glyph=key;const path=document.createElementNS(SVG_NS,"path");path.setAttribute("d",TABLE_GLYPHS.glyphs[key].d);svg.appendChild(path);return svg;}
